// Package filestore provides a small, filesystem-backed store for generated media.
package filestore

import (
	"crypto/rand"
	"errors"
	"fmt"
	"io"
	"mime"
	"os"
	"path/filepath"
	"strings"
	"time"
)

var (
	ErrInvalidRoot = errors.New("filestore root is required")
	ErrInvalidID   = errors.New("invalid filestore ID")
	ErrInvalidExt  = errors.New("invalid filestore extension")
)

// Store keeps generated files below Root. IDs are generated by Save/Write and
// are safe to use as URL path components and filesystem basenames.
type Store struct {
	root string
}

// File describes a regular file in the store.
type File struct {
	ID          string
	Size        int64
	ModifiedAt  time.Time
	ContentType string
}

// New creates a store rooted at root, creating the directory if necessary.
func New(root string) (*Store, error) {
	if strings.TrimSpace(root) == "" {
		return nil, ErrInvalidRoot
	}
	absolute, err := filepath.Abs(root)
	if err != nil {
		return nil, fmt.Errorf("resolve filestore root: %w", err)
	}
	if err := os.MkdirAll(absolute, 0o700); err != nil {
		return nil, fmt.Errorf("create filestore root: %w", err)
	}
	info, err := os.Stat(absolute)
	if err != nil {
		return nil, fmt.Errorf("stat filestore root: %w", err)
	}
	if !info.IsDir() {
		return nil, fmt.Errorf("filestore root is not a directory: %s", absolute)
	}
	return &Store{root: absolute}, nil
}

// NewStore is an alias for New.
func NewStore(root string) (*Store, error) { return New(root) }

// Root returns the absolute filesystem root used by the store.
func (s *Store) Root() string { return s.root }

// Save atomically writes data and returns a newly generated ID. ext may be
// supplied with or without its leading dot.
func (s *Store) Save(data []byte, ext string) (string, error) {
	ext, err := normalizeExtension(ext)
	if err != nil {
		return "", err
	}
	id, err := newID(ext)
	if err != nil {
		return "", fmt.Errorf("generate file ID: %w", err)
	}
	path, err := s.pathForID(id)
	if err != nil {
		return "", err
	}

	tmp, err := os.CreateTemp(s.root, ".filestore-*")
	if err != nil {
		return "", fmt.Errorf("create temporary media file: %w", err)
	}
	tmpName := tmp.Name()
	keep := false
	defer func() {
		_ = tmp.Close()
		if !keep {
			_ = os.Remove(tmpName)
		}
	}()
	if err := tmp.Chmod(0o600); err != nil {
		return "", fmt.Errorf("set temporary media permissions: %w", err)
	}
	if _, err := tmp.Write(data); err != nil {
		return "", fmt.Errorf("write media: %w", err)
	}
	if err := tmp.Sync(); err != nil {
		return "", fmt.Errorf("sync media: %w", err)
	}
	if err := tmp.Close(); err != nil {
		return "", fmt.Errorf("close temporary media file: %w", err)
	}
	if err := os.Rename(tmpName, path); err != nil {
		return "", fmt.Errorf("commit media file: %w", err)
	}
	keep = true
	return id, nil
}

// Write is an alias for Save.
func (s *Store) Write(data []byte, ext string) (string, error) { return s.Save(data, ext) }

// Read returns the complete contents of id.
func (s *Store) Read(id string) ([]byte, error) {
	path, err := s.pathForID(id)
	if err != nil {
		return nil, err
	}
	if err := s.rejectSymlink(path); err != nil {
		return nil, err
	}
	return os.ReadFile(path)
}

// Open opens id for reading. The caller owns and must close the returned file.
func (s *Store) Open(id string) (*os.File, error) {
	path, err := s.pathForID(id)
	if err != nil {
		return nil, err
	}
	if err := s.rejectSymlink(path); err != nil {
		return nil, err
	}
	return os.Open(path)
}

// Delete removes id. Missing files are reported as os.ErrNotExist.
func (s *Store) Delete(id string) error {
	path, err := s.pathForID(id)
	if err != nil {
		return err
	}
	if err := s.rejectSymlink(path); err != nil {
		return err
	}
	return os.Remove(path)
}

// ContentType returns the MIME type associated with a file extension.
func (s *Store) ContentType(id string) string { return ContentType(id) }

// ContentType returns a conservative MIME type based on the file extension.
func ContentType(id string) string {
	if typ := mime.TypeByExtension(strings.ToLower(filepath.Ext(id))); typ != "" {
		return typ
	}
	return "application/octet-stream"
}

// List returns regular, non-symlink files currently in the root.
func (s *Store) List() ([]File, error) {
	entries, err := os.ReadDir(s.root)
	if err != nil {
		return nil, fmt.Errorf("list filestore: %w", err)
	}
	files := make([]File, 0, len(entries))
	for _, entry := range entries {
		if !entry.Type().IsRegular() {
			continue
		}
		info, err := entry.Info()
		if err != nil {
			return nil, fmt.Errorf("stat media file %q: %w", entry.Name(), err)
		}
		files = append(files, File{ID: entry.Name(), Size: info.Size(), ModifiedAt: info.ModTime(), ContentType: ContentType(entry.Name())})
	}
	return files, nil
}

// Cleanup removes regular files older than age and returns their IDs. A
// non-positive age is rejected to avoid accidentally deleting the whole store.
func (s *Store) Cleanup(age time.Duration) ([]string, error) {
	if age <= 0 {
		return nil, fmt.Errorf("cleanup age must be positive")
	}
	entries, err := os.ReadDir(s.root)
	if err != nil {
		return nil, fmt.Errorf("list filestore for cleanup: %w", err)
	}
	cutoff := time.Now().Add(-age)
	removed := make([]string, 0)
	for _, entry := range entries {
		if !entry.Type().IsRegular() {
			continue
		}
		info, err := entry.Info()
		if err != nil {
			return removed, fmt.Errorf("stat media file %q: %w", entry.Name(), err)
		}
		if info.ModTime().Before(cutoff) {
			if err := os.Remove(filepath.Join(s.root, entry.Name())); err != nil {
				if errors.Is(err, os.ErrNotExist) {
					continue
				}
				return removed, fmt.Errorf("remove media file %q: %w", entry.Name(), err)
			}
			removed = append(removed, entry.Name())
		}
	}
	return removed, nil
}

func (s *Store) pathForID(id string) (string, error) {
	if id == "" || id == "." || id == ".." || strings.ContainsRune(id, 0) || strings.ContainsAny(id, `/\\`) {
		return "", ErrInvalidID
	}
	path := filepath.Join(s.root, id)
	if filepath.Dir(path) != s.root || filepath.Base(path) != id {
		return "", ErrInvalidID
	}
	return path, nil
}

func (s *Store) rejectSymlink(path string) error {
	info, err := os.Lstat(path)
	if err != nil {
		return err
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return ErrInvalidID
	}
	return nil
}

func normalizeExtension(ext string) (string, error) {
	ext = strings.TrimSpace(ext)
	if ext == "" {
		return "", ErrInvalidExt
	}
	if !strings.HasPrefix(ext, ".") {
		ext = "." + ext
	}
	if ext == "." || strings.ContainsAny(ext, `/\\`) || strings.ContainsRune(ext, 0) || filepath.Ext(ext) != ext {
		return "", ErrInvalidExt
	}
	return strings.ToLower(ext), nil
}

func newID(ext string) (string, error) {
	var random [16]byte
	if _, err := io.ReadFull(rand.Reader, random[:]); err != nil {
		return "", err
	}
	return fmt.Sprintf("%x%s", random, ext), nil
}
